def check_wcet_property(task_i, L1, L2):
    if L1 > L2:
        return task_i.C_L1 >= task_i.C_L2
    return True # Or handle L1 <= L2 case as needed

def determine_behavior_criticality(executed_jobs, criticality_levels):
    # criticality_levels is an ordered list, e.g., [LO, HI]
    for L in criticality_levels:
        all_jobs_within_L_budget = True
        for job in executed_jobs:
            if job.actual_execution_time > job.task.C_L:
                all_jobs_within_L_budget = False
                break
        if all_jobs_within_L_budget:
            return L
    return 'ERROR' # Or highest criticality if all jobs exceed even highest C

import math

def calculate_rta_smc(task_i, task_set):
    R_i = task_i.C_L_i # Initial estimate, using task's own criticality WCET
    while True:
        interference = 0
        for task_j in task_set:
            if task_j.priority > task_i.priority:
                # Determine effective WCET for interference
                effective_L = min(task_i.L, task_j.L)
                C_j_effective = task_j.get_C(effective_L)
                interference += math.ceil(R_i / task_j.T) * C_j_effective

        new_R_i = task_i.C_L_i + interference

        if new_R_i == R_i:
            return R_i
        elif new_R_i > task_i.D:
            return new_R_i
        R_i = new_R_i

