def calculate_rta_amc_rtb(task_i, task_set, R_LO_values):
    # This analysis is only for HI-criticality tasks
    if task_i.L != 'HI':
        return None

    R_LO_i = R_LO_values[task_i.id] # Pre-calculated R_LO_i for task_i

    R_star_i = task_i.C_HI # Initial estimate
    while True:
        hi_interference = 0
        lo_interference_capped = 0
        for task_j in task_set:
            if task_j.priority > task_i.priority:
                if task_j.L == 'HI':
                    hi_interference += math.ceil(R_star_i / task_j.T) * task_j.C_HI
                else: # LO-criticality task
                    # Interference from LO tasks is capped by R_LO_i
                    lo_interference_capped += math.ceil(R_LO_i / task_j.T) * task_j.C_LO

        new_R_star_i = task_i.C_HI + hi_interference + lo_interference_capped

        if new_R_star_i == R_star_i:
            return R_star_i
        elif new_R_star_i > task_i.D:
            return new_R_star_i
        R_star_i = new_R_star_i

