def calculate_I_L_s(s, task_i, task_set):
    I_L_s = 0
    for task_j in task_set:
        if task_j.L == 'LO' and task_j.priority > task_i.priority:
            num_jobs = math.floor(s / task_j.T) + 1
            I_L_s += num_jobs * task_j.C_LO
    return I_L_s

