def calculate_M_k_s_t(k, s, t):
    # k is a task object with T_k and D_k attributes
    term1 = math.floor((t - s - (k.T - k.D)) / k.T) + 1
    term2 = math.floor(t / k.T)
    return min(term1, term2)

