def calculate_rta_amc_method2_at_s(s, task_i, task_set):
    # This analysis is only for HI-criticality tasks
    if task_i.L != 'HI':
        return None

    I_L_s = calculate_I_L_s(s, task_i, task_set) # From Claim 8

    R_s_i = task_i.C_HI + I_L_s # Initial estimate
    while True:
        hi_hi_interference = 0
        for task_k in task_set:
            if task_k.L == 'HI' and task_k.priority > task_i.priority:
                M_k_s_R_s_i = calculate_M_k_s_t(task_k, s, R_s_i) # From Claim 9
                hi_hi_interference += (M_k_s_R_s_i * task_k.C_HI) + \
                                      ((math.floor(R_s_i / task_k.T) - M_k_s_R_s_i) * task_k.C_LO)

        new_R_s_i = task_i.C_HI + I_L_s + hi_hi_interference

        if new_R_s_i == R_s_i:
            return R_s_i
        elif new_R_s_i > task_i.D:
            return new_R_s_i
        R_s_i = new_R_s_i

