def calculate_rta_amc_method2_overall(task_i, task_set, R_LO_values):
    # This analysis is only for HI-criticality tasks
    if task_i.L != 'HI':
        return None

    R_LO_i = R_LO_values[task_i.id] # Pre-calculated R_LO_i for task_i

    # Generate candidate 's' values (release points of higher-priority LO tasks)
    candidate_s_values = set()
    candidate_s_values.add(0) # Always check s=0
    for task_j in task_set:
        if task_j.L == 'LO' and task_j.priority > task_i.priority:
            # Consider releases up to R_LO_i
            for k in range(math.floor(R_LO_i / task_j.T)):
                s_val = k * task_j.T
                if s_val < R_LO_i:
                    candidate_s_values.add(s_val)

    max_R_star_i = 0
    for s_val in sorted(list(candidate_s_values)):
        current_R_s_i = calculate_rta_amc_method2_at_s(s_val, task_i, task_set) # From Claim 10
        if current_R_s_i is None: # Handle unschedulable at this s_val
            return float('inf') # Indicate unschedulable
        max_R_star_i = max(max_R_star_i, current_R_s_i)

    return max_R_star_i

