        candidates_to_test = []
        if longest_deadline_lo_task: candidates_to_test.append(longest_deadline_lo_task)
        if longest_deadline_hi_task: candidates_to_test.append(longest_deadline_hi_task)

        for candidate_task in candidates_to_test:
            # Temporarily assign candidate_task the lowest priority
            # and all other remaining_tasks higher priorities (e.g., DM within their criticality)
            # Then run schedulability_test_func for candidate_task
